$entry = static function (
    ?int $id,
    string $groupName,
    string $name,
    string $en,
    string $vi,
    array $modules = ['Core'],
    bool $forWeb = false,
    bool $forAdm = true,
    bool $forApp = false,
    ?string $status = 'status_published',
    string $createdAt = '2026-03-14 18:15:00',
    ?string $updatedAt = null,
): array {
    return [
        // No 'id': the importer finds rows by name, and an id only links an existing row that may hold another key.
        'modules' => $modules,
        'group_name' => $groupName,
        'name' => $name,
        'text' => [
            'en' => $en,
            'vi' => $vi,
        ],
        'for_web' => $forWeb ? 1 : 0,
        'for_adm' => $forAdm ? 1 : 0,
        'for_app' => $forApp ? 1 : 0,
        'status' => $status,
        'created_at' => $createdAt,
        'updated_at' => $updatedAt ?? $createdAt,
    ];
};

