    // ── Agentic Schedules — i18n ──
    $entry(994500, 'text', 'text.agentic.schedules.section_desc', 'Use for safe recurring agent operations. Best suited for scheduled maintenance profiles.', 'Dùng để cho agent chạy việc định kỳ an toàn. Phù hợp nhất với profile bảo trì theo lịch.'),
    $entry(994501, 'text', 'text.agentic.schedules.what_is_scheduler', 'What is this scheduler for?', 'Scheduler này dùng để làm gì?'),
    $entry(994502, 'text', 'text.agentic.schedules.what_is_scheduler_desc', 'Create a schedule so the agent can automatically repeat low-risk tasks such as health checks, quick summaries, or periodic reviews. If unsure, only use it for the <strong>Scheduled maintenance</strong> profile. If you only want to run once, use <strong>Run now</strong> or <strong>Run once</strong> in the table below instead of creating a new schedule.', 'Tạo lịch để agent tự chạy lặp lại các việc ít rủi ro như kiểm tra sức khỏe, tổng hợp nhanh, hoặc rà soát định kỳ. Nếu bạn chưa chắc, chỉ nên dùng cho profile <strong>Scheduled maintenance</strong>. Nếu chỉ muốn chạy một lần, dùng <strong>Run now</strong> hoặc <strong>Run once</strong> ở bảng bên dưới thay vì tạo lịch mới.'),
    $entry(994503, 'text', 'text.agentic.schedules.select_profile_hint', 'Please select a profile from the table above.', 'Hãy chọn profile ở bảng bên trên.'),
    $entry(994504, 'text', 'text.agentic.schedules.tool_call_hint', 'This tool will be called on the schedule you create.', 'Tool này sẽ được gọi theo lịch bạn tạo.'),
    $entry(994505, 'text', 'text.agentic.schedules.select_tool_hint', 'Please select a tool from the Tool Definitions table.', 'Hãy chọn tool ở bảng Tool Definitions.'),
    $entry(994506, 'text', 'text.agentic.schedules.cadence_hint', 'If unsure what to pick, start with <strong>Every day</strong>.', 'Nếu chưa chắc nên chọn gì, hãy bắt đầu với <strong>Mỗi ngày</strong>.'),
    $entry(994507, 'text', 'text.agentic.schedules.advanced_hint', 'These fields are for special operational cases. If unsure, leave them blank.', 'Các trường này dành cho ca vận hành đặc biệt. Nếu bạn không chắc, cứ để trống.'),
    $entry(994508, 'text', 'text.agentic.schedules.run_now_desc', '<strong>Run now</strong> runs once immediately and keeps the current cadence.', '<strong>Run now</strong> chạy ngay một lần và vẫn giữ cadence hiện tại.'),
    $entry(994509, 'text', 'text.agentic.schedules.run_once_desc', '<strong>Run once</strong> runs only once and returns to <strong>paused</strong> after finishing.', '<strong>Run once</strong> chỉ chạy một lần và sẽ quay về <strong>paused</strong> sau khi kết thúc.'),
    $entry(994510, 'text', 'text.agentic.schedules.resume_desc', 'Re-enables the recurring cadence and immediately triggers one run.', 'Bật lại cadence định kỳ và đồng thời khởi chạy ngay một lần.'),
