    $entry(null, 'text', 'text.modules.install.drawer.step.migrate_upgrade', 'Run only the new data updates and refresh the site.', 'Chỉ chạy các cập nhật dữ liệu mới và làm mới website.'),
    $entry(null, 'text', 'text.modules.install.drawer.backup_notice', 'A backup of the database is taken before anything changes. If the backup fails, nothing is installed.', 'Cơ sở dữ liệu được sao lưu trước khi có bất kỳ thay đổi nào. Nếu sao lưu lỗi, sẽ không cài gì.'),
    $entry(null, 'text', 'text.modules.install.drawer.upgrade_backup_notice', 'A backup of the database is taken before anything changes. If the backup fails, nothing is changed. If the upgrade fails, the version in use is put back automatically.', 'Cơ sở dữ liệu được sao lưu trước khi có bất kỳ thay đổi nào. Nếu sao lưu lỗi, sẽ không đổi gì. Nếu nâng cấp lỗi, bản đang dùng được tự động trả lại.'),
