    $entry(null, 'text', 'text.modules.error.install_config_cache_failed', 'The setting was saved, but the website could not reload its configuration. Try again in a moment.', 'Thiết lập đã được lưu nhưng website chưa nạp lại được cấu hình. Hãy thử lại sau ít phút.'),
    $entry(null, 'text', 'text.modules.error.install_enable_failed', 'The module could not be switched on. It was switched off again, and the backup taken before the install is kept.', 'Không bật được module. Module đã được tắt lại và bản sao lưu trước khi cài vẫn được giữ.'),
    $entry(null, 'text', 'text.modules.error.install_failed', 'The install stopped because of an unexpected problem. Nothing was switched on.', 'Việc cài dừng lại vì một sự cố bất ngờ. Chưa có gì được bật.'),
    $entry(null, 'text', 'text.modules.error.install_hub_unavailable', 'The iSPA platform could not be reached. Try again in a few minutes.', 'Không kết nối được nền tảng iSPA. Hãy thử lại sau vài phút.'),
    $entry(null, 'text', 'text.modules.error.install_job_failed', 'The install did not finish. Check the history and try again.', 'Việc cài chưa hoàn tất. Hãy xem lịch sử cài và thử lại.'),
    $entry(null, 'text', 'text.modules.error.install_migrate_failed', 'Preparing the module data failed. The module was switched off again. Restore the backup taken before the install if your data changed.', 'Chuẩn bị dữ liệu cho module không thành công. Module đã được tắt lại. Hãy khôi phục bản sao lưu trước khi cài nếu dữ liệu đã thay đổi.'),
    $entry(null, 'text', 'text.modules.error.install_needs_db_status', 'This site is not set up to install modules yet. Ask whoever runs the server to finish the setup.', 'Website chưa được thiết lập để cài module. Hãy nhờ người quản trị máy chủ hoàn tất thiết lập.'),
    $entry(null, 'text', 'text.modules.error.install_no_runtime_folder', 'This site has no folder for installed modules. Ask whoever runs the server to create it.', 'Website chưa có thư mục chứa module đã cài. Hãy nhờ người quản trị máy chủ tạo thư mục này.'),
    $entry(null, 'text', 'text.modules.error.install_no_trusted_key', 'This site cannot check module signatures yet, so no package can be installed. Ask whoever runs the server to finish the setup.', 'Website chưa kiểm tra được chữ ký của module nên chưa cài được gói nào. Hãy nhờ người quản trị máy chủ hoàn tất thiết lập.'),
    $entry(null, 'text', 'text.modules.error.install_queue_sync', 'Background work is not set up on this site, so installs cannot run. Ask whoever runs the server to switch on the queue.', 'Website chưa bật xử lý nền nên chưa chạy được việc cài. Hãy nhờ người quản trị máy chủ bật hàng đợi.'),
    $entry(null, 'text', 'text.modules.error.install_no_runner', 'This website\'s automatic tasks are not running right now, so modules cannot be installed yet. Nothing was changed. Ask whoever manages the server to turn on the every-minute schedule (cron) for this website, then try again a few minutes later.', 'Các việc tự động của website hiện không chạy nên chưa cài được module. Chưa có gì bị thay đổi. Hãy nhờ người quản trị máy chủ bật lịch chạy tự động mỗi phút (cron) cho website, rồi thử lại sau vài phút.', updatedAt: '2026-11-25 23:30:00'),
    $entry(null, 'text', 'text.modules.error.install_queue_timeout', 'This website is not ready to run a module install, so nothing was changed. Ask whoever manages the website to update iSPA CMS to the latest version, then try again.', 'Website chưa sẵn sàng để cài module nên chưa có gì bị thay đổi. Hãy nhờ người quản trị website cập nhật iSPA CMS lên bản mới nhất, rồi thử lại.', updatedAt: '2026-11-25 23:30:00'),
    $entry(null, 'text', 'text.modules.error.install_running', 'Another module install is still running. Wait until it finishes.', 'Đang có một lần cài module khác chạy. Hãy đợi cho đến khi xong.'),
    $entry(null, 'text', 'text.modules.error.install_staging', 'This site could not prepare a working folder for the install.', 'Website không chuẩn bị được thư mục làm việc để cài.'),
    $entry(null, 'text', 'text.modules.error.install_ticket_invalid', 'The iSPA platform did not allow the download. Check that this site is licensed and try again.', 'Nền tảng iSPA không cho phép tải. Hãy kiểm tra website đã được cấp phép chưa rồi thử lại.'),
