    $entry(null, 'text', 'text.modules.error.pending_migrations', 'The website still has {count} data updates that have not been applied, so modules cannot be installed yet. Ask whoever manages the server to apply them, then try again.', 'Website còn {count} bản cập nhật dữ liệu chưa được áp dụng nên chưa cài được module. Hãy nhờ người quản trị máy chủ áp dụng chúng, rồi thử lại.', updatedAt: '2026-11-25 23:30:00'),
    $entry(null, 'text', 'text.modules.error.php_too_old', 'This module needs a newer PHP version (PHP {required} or newer; this server runs {running}).', 'Module này cần phiên bản PHP mới hơn (PHP {required} trở lên; máy chủ đang chạy {running}).'),
