    $entry(null, 'text', 'text.modules.error.place_link_exists', 'The module could not be placed because something already uses its place.', 'Không đặt được module vì vị trí của nó đã có thứ khác.'),
    $entry(null, 'text', 'text.modules.error.place_staged_invalid', 'The unpacked module is not valid, so it was not placed.', 'Module sau khi giải nén không hợp lệ nên chưa được đặt vào.'),
