    $entry(null, 'text', 'text.modules.error.requires_unmet', 'This module needs other modules that are missing, switched off or too old: {modules}.', 'Module này cần các module khác nhưng chúng đang thiếu, đang tắt hoặc quá cũ: {modules}.'),
