    $entry(null, 'text', 'text.modules.core_update.load_failed', 'Could not read the iSPA CMS update status. Try again.', 'Không đọc được tình trạng cập nhật iSPA CMS. Hãy thử lại.', updatedAt: '2026-11-22 23:30:00'),
