    $entry(null, 'text', 'text.modules.core_update.confirm.text', 'The site files and the database are backed up before anything changes. If the check after the update fails, the old files are put back.', 'Tệp của website và cơ sở dữ liệu được sao lưu trước khi có bất kỳ thay đổi nào. Nếu bước kiểm tra sau cập nhật lỗi, tệp cũ được trả lại.'),
    $entry(null, 'text', 'text.modules.core_update.confirm.backup', 'I understand a backup will be taken and I have my own copy of the site data', 'Tôi hiểu hệ thống sẽ sao lưu và tôi đã có bản sao dữ liệu của website'),
    $entry(null, 'text', 'text.modules.core_update.error.generic', 'The update could not be started. Try again, or run ./ispa upgrade on the server.', 'Không bắt đầu được cập nhật. Hãy thử lại hoặc chạy ./ispa upgrade trên máy chủ.'),
    $entry(null, 'text', 'text.modules.core_update.issue.CORE_MODIFIED', 'Some iSPA CMS files were changed on this site. Move your changes into your own project or module, or update from the command line.', 'Một số tệp của iSPA CMS đã bị sửa trên website này. Hãy chuyển phần sửa vào dự án hoặc module riêng, hoặc cập nhật bằng dòng lệnh.', updatedAt: '2026-11-22 23:30:00'),
    $entry(null, 'text', 'text.modules.core_update.issue.CORE_CUSTOM_DEPS', 'This site has its own PHP packages, so it has to be updated from the command line.', 'Website có gói PHP riêng nên phải cập nhật bằng dòng lệnh.'),
    $entry(null, 'text', 'text.modules.core_update.issue.CORE_CUSTOM_DEPS_CONFLICT', 'This site\'s own PHP packages do not fit the new iSPA CMS version. Update from the command line to see what conflicts.', 'Gói PHP riêng của website không khớp với bản iSPA CMS mới. Hãy cập nhật bằng dòng lệnh để xem chỗ xung đột.', updatedAt: '2026-11-22 23:30:00'),
    $entry(null, 'text', 'text.modules.core_update.issue.CORE_NOT_WRITABLE', 'The server is not allowed to write some iSPA CMS folders. Fix the folder permissions or update from the command line.', 'Máy chủ chưa được ghi vào một số thư mục của iSPA CMS. Hãy sửa quyền thư mục hoặc cập nhật bằng dòng lệnh.', updatedAt: '2026-11-22 23:30:00'),
    $entry(null, 'text', 'text.modules.core_update.issue.CORE_DISK', 'There is not enough free disk space for the update.', 'Ổ đĩa không đủ chỗ trống để cập nhật.'),
    $entry(null, 'text', 'text.modules.core_update.issue.CORE_PHP', 'The PHP version on the server is too old for the new iSPA CMS version.', 'Phiên bản PHP trên máy chủ quá cũ so với bản iSPA CMS mới.', updatedAt: '2026-11-22 23:30:00'),
    $entry(null, 'text', 'text.modules.core_update.issue.CORE_UPGRADE_INTERRUPTED', 'A previous update did not finish. Put the old files back, then try again.', 'Lần cập nhật trước chưa xong. Hãy khôi phục tệp cũ rồi thử lại.', updatedAt: '2026-11-22 12:00:00'),
    $entry(null, 'text', 'text.modules.core_update.issue.CORE_NO_QUEUE', 'The background worker is not running, so the update cannot start from here.', 'Tiến trình chạy nền chưa hoạt động nên chưa thể bắt đầu cập nhật từ đây.'),
    $entry(null, 'text', 'text.modules.core_update.issue.CORE_NO_MANIFEST', 'This site was not installed from an iSPA CMS package, so it cannot update itself.', 'Website này không được cài từ gói iSPA CMS nên không tự cập nhật được.'),
    $entry(null, 'text', 'text.modules.core_update.issue.unknown', 'The update cannot start from here. Use the command line instead.', 'Chưa thể bắt đầu cập nhật từ đây. Hãy dùng dòng lệnh.'),
    $entry(null, 'text', 'text.modules.core_update.issue.CORE_NO_RUNNER', 'This server has no background runner that can update iSPA CMS yet.', 'Máy chủ chưa có tiến trình nền để cập nhật iSPA CMS.', updatedAt: '2026-11-22 23:30:00'),
    $entry(null, 'text', 'text.modules.core_update.issue.CORE_RELEASE_LAYOUT', 'This site is installed as release folders, so update it from the command line.', 'Website này được cài theo dạng thư mục phát hành nên cần cập nhật bằng dòng lệnh.', updatedAt: '2026-11-22 12:00:00'),
    $entry(null, 'text', 'text.modules.core_update.issue.CORE_MODULE_INSTALL_RUNNING', 'A module is being installed or updated. Try again when it has finished.', 'Đang cài hoặc cập nhật một module. Hãy thử lại khi việc đó xong.', updatedAt: '2026-11-22 18:00:00'),
    $entry(null, 'text', 'text.modules.core_update.issue.CORE_CODE_DIR_SHARED', "The website's code folder can be changed by the web server user, so updates from this page are switched off. The person who manages the server needs to fix the folder permissions.", "Thư mục mã nguồn của website đang cho tài khoản web ghi vào nên chưa thể cập nhật từ trang này. Người quản lý máy chủ cần sửa quyền thư mục.", updatedAt: '2026-11-22 22:00:00'),
    $entry(null, 'text', 'text.modules.core_update.runner_setup', 'To keep the code with the account {user}, the person who manages the server adds this line once to its crontab. After that, updates start from this page.', 'Nếu muốn mã nguồn vẫn thuộc tài khoản {user}, người quản lý máy chủ thêm một lần dòng sau vào lịch chạy (crontab) của tài khoản đó. Sau đó có thể cập nhật ngay tại trang này.', updatedAt: '2026-11-24 10:00:00'),
    $entry(null, 'text', 'text.modules.core_update.runner_setup_root', "The website's code belongs to root, so updates from this page are not possible yet.", "Mã nguồn của website đang thuộc tài khoản root nên chưa thể cập nhật từ trang này.", updatedAt: '2026-11-24 10:00:00'),
    $entry(null, 'text', 'text.modules.core_update.waiting', 'Waiting for the server to start the update (usually under a minute).', 'Đang chờ máy chủ bắt đầu cập nhật (thường dưới 1 phút).', updatedAt: '2026-11-22 12:00:00'),
    $entry(null, 'text', 'text.modules.core_update.action.restore', 'Put the old files back', 'Khôi phục tệp cũ', updatedAt: '2026-11-22 12:00:00'),
    $entry(null, 'text', 'text.modules.core_update.action.copy', 'Copy the line', 'Sao chép dòng lệnh', updatedAt: '2026-11-22 12:00:00'),
    $entry(null, 'text', 'text.modules.core_update.action.copied', 'Copied', 'Đã sao chép', updatedAt: '2026-11-22 12:00:00'),
    $entry(null, 'text', 'text.modules.core_update.restore_confirm.title', 'Put the previous iSPA CMS files back?', 'Khôi phục tệp iSPA CMS bản trước?', updatedAt: '2026-11-22 23:30:00'),
    $entry(null, 'text', 'text.modules.core_update.restore_confirm.text', 'The files from before the unfinished update are put back. The database is not changed; it was backed up before the update.', 'Hệ thống đưa lại các tệp trước lần cập nhật chưa xong. Cơ sở dữ liệu không đổi; dữ liệu đã được sao lưu trước khi cập nhật.', updatedAt: '2026-11-22 12:00:00'),
    $entry(null, 'text', 'text.modules.core_update.restore_confirm.check', 'I want to put the old files back', 'Tôi muốn khôi phục tệp cũ', updatedAt: '2026-11-22 12:00:00'),
    $entry(null, 'text', 'text.modules.core_update.restore_confirm.error', 'The request to put the old files back could not be sent. Try again.', 'Chưa gửi được yêu cầu khôi phục tệp cũ. Hãy thử lại.', updatedAt: '2026-11-22 12:00:00'),
    $entry(null, 'text', 'text.modules.core_update.result.updated', 'iSPA CMS was updated to {version}.', 'Đã cập nhật iSPA CMS lên bản {version}.', updatedAt: '2026-11-22 23:30:00'),
    $entry(null, 'text', 'text.modules.core_update.result.restored', 'The previous iSPA CMS files were put back.', 'Đã khôi phục tệp iSPA CMS bản trước.', updatedAt: '2026-11-22 23:30:00'),
    $entry(null, 'text', 'text.modules.core_update.result.CORE_RUNNER_TIMEOUT', 'The server did not start the update within 15 minutes. Check that the background runner is set up, then try again.', 'Máy chủ không bắt đầu cập nhật trong 15 phút. Hãy kiểm tra tiến trình nền đã được cài chưa rồi thử lại.', updatedAt: '2026-11-22 12:00:00'),
    $entry(null, 'text', 'text.modules.core_update.result.CORE_RUNNER_DIED', 'The background runner stopped during the update. If the site has problems, put the old files back.', 'Tiến trình nền dừng giữa chừng khi cập nhật. Nếu website gặp lỗi, hãy khôi phục tệp cũ.', updatedAt: '2026-11-22 12:00:00'),
    $entry(null, 'text', 'text.modules.core_update.result.failed', 'The update did not finish. The old files were put back where possible; nothing else changed.', 'Cập nhật chưa xong. Hệ thống đã đưa lại tệp cũ khi có thể; ngoài ra không có gì thay đổi.', updatedAt: '2026-11-22 12:00:00'),
    $entry(null, 'text', 'text.modules.core_update.result.restore_failed', 'The old files could not be put back. Try again, or ask the person who manages the server.', 'Chưa khôi phục được tệp cũ. Hãy thử lại hoặc nhờ người quản lý máy chủ.', updatedAt: '2026-11-22 12:00:00'),
    $entry(null, 'text', 'text.modules.core_update.agent_prompt.title', "Instructions for an AI agent", "Hướng dẫn cho trợ lý AI", updatedAt: '2026-11-22 20:00:00'),
    $entry(null, 'text', 'text.modules.core_update.agent_prompt.help', "If the person who manages the server uses an AI coding agent (Claude Code or similar), they can paste these instructions into it.", "Nếu người quản lý máy chủ dùng trợ lý lập trình AI (như Claude Code), họ có thể dán hướng dẫn này vào đó.", updatedAt: '2026-11-22 20:00:00'),
    $entry(null, 'text', 'text.modules.core_update.agent_prompt.copy', "Copy the instructions", "Sao chép hướng dẫn", updatedAt: '2026-11-22 20:00:00'),
    $entry(null, 'text', 'text.modules.core_update.agent_prompt.body', "Task: set up the website's iSPA CMS update runner, a small job that runs every minute so iSPA CMS can be updated from the admin.\n1. Read the crontab of the account {user}: crontab -u {user} -l\n   If it already has the line below, change nothing.\n2. Otherwise add exactly this line to the crontab of the account {user}, even when you are signed in as another account, and keep every line that is already there:\n{line}\n   For example: ( crontab -u {user} -l 2>/dev/null; echo \"{line}\" ) {'|'} crontab -u {user} -\n   crontab -u {user} needs root (for example through sudo). When you are signed in as {user} yourself, use the same commands without -u {user}.\n\nCheck:\n- Within about a minute the file {base}/storage/app/ispa/core-runner.json appears.\n- After that, the \"iSPA CMS\" card in the admin (Settings > Modules) no longer asks for the runner.", "Việc cần làm: cài tiến trình nền cập nhật iSPA CMS cho website. Đây là một việc nhỏ chạy mỗi phút, giúp cập nhật iSPA CMS ngay từ trang quản trị.\n1. Xem lịch chạy (crontab) của tài khoản {user}: crontab -u {user} -l\n   Nếu đã có dòng bên dưới thì không thay đổi gì.\n2. Nếu chưa có, thêm đúng dòng sau vào crontab của tài khoản {user}, kể cả khi bạn đang đăng nhập bằng tài khoản khác, và giữ nguyên các dòng đang có:\n{line}\n   Ví dụ: ( crontab -u {user} -l 2>/dev/null; echo \"{line}\" ) {'|'} crontab -u {user} -\n   Lệnh crontab -u {user} cần quyền root (ví dụ qua sudo). Nếu bạn đang đăng nhập bằng chính tài khoản {user}, dùng các lệnh trên nhưng bỏ phần -u {user}.\n\nKiểm tra:\n- Trong khoảng một phút, tệp {base}/storage/app/ispa/core-runner.json xuất hiện.\n- Sau đó, thẻ \"iSPA CMS\" trong trang Quản lý module của trang quản trị không còn báo thiếu tiến trình nền.", updatedAt: '2026-11-22 23:30:00'),
    $entry(null, 'text', 'text.modules.core_update.agent_prompt.modified', "The website also has iSPA CMS files that were changed on the site, so iSPA CMS cannot be updated from the admin yet:\n{files}\n\nFor each of these files:\n1. Show its diff against the same file in the release zip of the installed version (the installed version is in {base}/core-manifest.json).\n2. Propose where the change should live instead: in the website's own project folder (under projects/) or in a module.\nDo not restore, overwrite or delete any of these files without the website owner's OK.", "Website còn có tệp của iSPA CMS đã bị sửa ngay trên website nên chưa thể cập nhật iSPA CMS từ trang quản trị:\n{files}\n\nVới từng tệp trên:\n1. Cho xem phần khác biệt (diff) so với cùng tệp đó trong gói zip của phiên bản đang cài (phiên bản đang cài ghi trong {base}/core-manifest.json).\n2. Đề xuất nơi nên đặt phần sửa đó: trong thư mục dự án riêng của website (bên trong projects/) hoặc trong một module.\nKhông khôi phục, ghi đè hay xoá tệp nào trong số này khi chưa được chủ website đồng ý.", updatedAt: '2026-11-22 23:30:00'),
    $entry(null, 'text', 'text.modules.core_update.agent_prompt.intro', "You are working on a Linux server that hosts an iSPA CMS website.\n\nWebsite folder: {base}\nAccount that owns the code: {user}", "Bạn đang làm việc trên một máy chủ Linux có website iSPA CMS.\n\nThư mục website: {base}\nTài khoản sở hữu mã nguồn: {user}", updatedAt: '2026-11-22 22:00:00'),
    $entry(null, 'text', 'text.modules.core_update.agent_prompt.code_dir_shared', "The website's code folder can be written by other accounts (for example the web server user), so updates from the admin are switched off.\n1. Report the owner, group and mode of the code folders: stat -c '%U:%G %a' {base} {base}/.ispa-runner {base}/app {base}/cms {base}/vendor\n2. Propose chmod go-w on the code folders only (never on storage/ or bootstrap/cache).\nChange nothing without the website owner's OK.", "Thư mục mã nguồn của website đang cho tài khoản khác (ví dụ tài khoản web) ghi vào nên việc cập nhật từ trang quản trị đang tắt.\n1. Báo lại chủ sở hữu, nhóm và quyền của các thư mục mã nguồn: stat -c '%U:%G %a' {base} {base}/.ispa-runner {base}/app {base}/cms {base}/vendor\n2. Đề xuất chmod go-w chỉ cho các thư mục mã nguồn (không bao giờ cho storage/ hay bootstrap/cache).\nKhông thay đổi gì khi chưa được chủ website đồng ý.", updatedAt: '2026-11-22 23:00:00'),
    $entry(null, 'text', 'text.modules.core_update.agent_prompt.limits', "Hard limits:\n- Never make code files or folders writable by group or others (no chmod 775 or 777).\n- Never edit the iSPA CMS files of the website.\n- Do not change sudoers.\n- Never print or repeat values from .env.\n- Ask before you do anything that is not on this list.\n\nWhen you are done, report briefly what you changed (for example whose crontab and which line) and what the checks showed.", "Giới hạn bắt buộc:\n- Không cho nhóm hay người khác ghi vào tệp hoặc thư mục mã nguồn (không chmod 775 hay 777).\n- Không sửa tệp của iSPA CMS trên website.\n- Không thay đổi sudoers.\n- Không in ra hay nhắc lại giá trị nào trong .env.\n- Hỏi trước khi làm bất kỳ việc gì ngoài danh sách này.\n\nKhi xong, hãy báo lại ngắn gọn đã thay đổi gì (ví dụ crontab của tài khoản nào, dòng nào) và kết quả kiểm tra.", updatedAt: '2026-11-24 10:00:00'),
    $entry(null, 'text', 'text.background_tasks.type.core_upgrade', 'iSPA CMS update', 'Cập nhật iSPA CMS', updatedAt: '2026-11-22 23:30:00'),
