    $entry(null, 'text', 'text.modules.core_update.managed', 'iSPA keeps this website up to date.', 'Website này do iSPA cập nhật.', createdAt: '2026-11-22 23:30:00'),
    $entry(null, 'text', 'text.modules.core_update.needs_module_update', 'Update these modules first: {modules}', 'Hãy cập nhật các module này trước: {modules}', createdAt: '2026-11-22 23:30:00'),
    // Core update card: one-line owner fix and "Check again" (2026-11-24).
    $entry(null, 'text', 'text.modules.core_update.fix_owner', 'The simplest fix: the person who manages the server runs this command once, so the website folder belongs to the web server account ({user}). Updates then run from this page on their own. Then press Check again.', 'Cách đơn giản nhất: người quản lý máy chủ chạy một lần lệnh dưới đây để thư mục website thuộc tài khoản web ({user}). Sau đó việc cập nhật tự chạy từ trang này. Chạy xong, bấm Kiểm tra lại.', createdAt: '2026-11-24 10:00:00'),
