    $entry(null, 'text', 'text.modules.core_row_note', 'Updated together with iSPA CMS.', 'Được cập nhật cùng iSPA CMS.', createdAt: '2026-11-22 23:30:00'),
    $entry(null, 'text', 'text.modules.support.env.core_module_version', 'Core module version (technical)', 'Phiên bản module Core (kỹ thuật)', createdAt: '2026-11-22 23:30:00'),
    // Connect screen wording follows the customer portal: "Secret code" / "Mã bí mật" (2026-11-19).
    $entry(null, 'text', 'text.site_connect.portal_hint', 'No secret code yet? Create an account at ispa.tech, open "Websites & domains", choose "Connect a website", enter this domain and choose "Create website codes".', 'Chưa có mã bí mật? Tạo tài khoản tại ispa.tech, vào "Website & tên miền", chọn "Kết nối website", nhập tên miền này rồi bấm "Tạo mã cho website".', updatedAt: '2026-11-19 23:00:00'),
    $entry(null, 'text', 'text.site_connect.site_secret', 'Secret code', 'Mã bí mật', updatedAt: '2026-11-19 23:00:00'),
    $entry(null, 'text', 'text.site_connect.site_secret_help', 'The portal shows this code only once, right after "Create website codes". Lost it? Create a new one there.', 'Cổng chỉ hiện mã này một lần, ngay sau khi bấm "Tạo mã cho website". Mất mã thì tạo mã mới trên cổng.', updatedAt: '2026-11-19 23:00:00'),
    $entry(null, 'text', 'text.site_connect.pending_text', 'iSPA Hub has received the code and is checking that this website really is yours. This usually takes a few minutes.', 'iSPA Hub đã nhận mã và đang kiểm tra website này có đúng là của bạn không. Việc này thường mất vài phút.', updatedAt: '2026-11-19 23:00:00'),
    $entry(null, 'text', 'text.site_connect.invalid_input', 'Please fill in the website address, the secret code and the setup code.', 'Hãy điền đủ địa chỉ website, mã bí mật và mã cài đặt.', updatedAt: '2026-11-19 23:00:00'),
    $entry(null, 'text', 'text.site_connect.credentials_refused', 'iSPA Hub does not accept this website address or secret code. Check what you copied from the portal.', 'iSPA Hub không nhận địa chỉ website hoặc mã bí mật này. Kiểm tra lại thông tin sao chép từ cổng.', updatedAt: '2026-11-19 23:00:00'),
    $entry(null, 'text', 'text.site_connect.managed_by_env', 'This website already has its code in the server settings, so it cannot be changed here. Please contact the server administrator.', 'Mã của website này đã được cài sẵn trong cấu hình máy chủ nên không đổi được ở đây. Hãy liên hệ người quản trị máy chủ.', updatedAt: '2026-11-19 23:00:00'),
    $entry(null, 'text', 'text.site_connect.reason.wrong_answer', 'The secret code does not match this website. Check the code.', 'Mã bí mật không khớp với website này. Kiểm tra lại mã.', updatedAt: '2026-11-19 23:00:00'),
    $entry(null, 'text', 'text.site_connect.reason.secret_expired', 'The secret code waited too long to be connected. Create a new code in the portal.', 'Mã bí mật đã hết thời gian chờ kết nối. Hãy tạo mã mới trên cổng.', updatedAt: '2026-11-19 23:00:00'),
