    $entry(null, 'text', 'text.dashboard.band.intro', 'Posts, pages, SEO and users work right away. Connect to iSPA Hub to install more modules (digital library, journal, online classes…), use paid modules and the iSPA services.', 'Bài viết, trang, SEO, người dùng đều dùng được ngay. Kết nối với iSPA Hub để cài thêm module (thư viện số, tạp chí, lớp học…), dùng module trả phí và các dịch vụ iSPA.', updatedAt: '2026-11-19 23:30:00'),
    $entry(null, 'text', 'text.dashboard.band.step1', 'Create a free account at ispa.tech and confirm your email.', 'Tạo tài khoản miễn phí tại ispa.tech và xác nhận email.', updatedAt: '2026-11-19 23:30:00'),
    $entry(null, 'text', 'text.dashboard.band.step2', 'In the portal open "Websites & domains", choose "Connect a website", enter this domain and choose "Create website codes". Copy the secret code.', 'Trên cổng: vào "Website & tên miền", chọn "Kết nối website", nhập tên miền này rồi bấm "Tạo mã cho website". Chép mã bí mật.', updatedAt: '2026-11-19 23:30:00'),
    $entry(null, 'text', 'text.dashboard.band.step3', 'Choose "Connect to iSPA Hub" below and paste the secret code and the setup code.', 'Bấm "Kết nối iSPA Hub" bên dưới, dán mã bí mật và mã cài đặt.', updatedAt: '2026-11-19 23:30:00'),
