    $entry(null, 'text', 'text.workflow.package.copy_chosen_hint', 'The workflow already on this site stays as it is. The copy is named "{name}"; you can rename it after installing.', 'Quy trình đang có trên website được giữ nguyên. Bản sao có tên "{name}"; bạn có thể đổi tên sau khi cài.', updatedAt: '2026-11-25 01:30:00'),
