    $entry(null, 'text', 'text.workflow.package.bindings_title', 'Choose what the workflow uses on this site', 'Chọn những thứ quy trình sẽ dùng trên website này', updatedAt: '2026-11-24 23:50:00'),
    $entry(null, 'text', 'text.workflow.package.bindings_hint', 'The file does not carry passwords, people or records of the other site. Choose the matching ones here.', 'Tệp không mang theo mật khẩu, người dùng hay bản ghi của website gốc. Hãy chọn những thứ tương ứng trên website này.', updatedAt: '2026-11-24 23:50:00'),
    $entry(null, 'text', 'text.workflow.package.warnings_title', 'Before you switch it on', 'Lưu ý trước khi bật quy trình', updatedAt: '2026-11-24 23:50:00'),
    $entry(null, 'text', 'text.workflow.package.dry_run_title', 'Safe test run', 'Chạy thử an toàn', updatedAt: '2026-11-24 23:50:00'),
    $entry(null, 'text', 'text.workflow.package.dry_run_safe', 'The site walked through the workflow with sample data. Nothing was sent, nothing was saved and no money was spent.', 'Website đã đi thử qua quy trình bằng dữ liệu mẫu. Không có gì được gửi đi, không có gì được lưu và không tốn khoản phí nào.', updatedAt: '2026-11-24 23:50:00'),
    $entry(null, 'text', 'text.workflow.package.dry_run_none', 'No test run could be made for this file. You can still install it and try it in the designer.', 'Chưa chạy thử được với tệp này. Bạn vẫn có thể cài rồi thử trong trình thiết kế.', updatedAt: '2026-11-24 23:50:00'),
    $entry(null, 'text', 'text.workflow.package.dry_run_blank', 'The file has no sample data, so the test used a blank record. Steps that branch on data may go another way when it really runs.', 'Tệp không kèm dữ liệu mẫu nên lần chạy thử dùng một bản ghi trống. Các bước rẽ nhánh theo dữ liệu có thể đi hướng khác khi chạy thật.', updatedAt: '2026-11-24 23:50:00'),
    $entry(null, 'text', 'text.workflow.package.dry_run_completed', 'The test run went through {count} steps without errors.', 'Lần chạy thử đã đi qua {count} bước và không gặp lỗi.', updatedAt: '2026-11-24 23:50:00'),
    $entry(null, 'text', 'text.workflow.package.dry_run_stopped', 'The test run stopped before the end, often because the sample data is not enough. This does not prevent installing. See the steps below.', 'Lần chạy thử dừng lại giữa chừng, thường do dữ liệu mẫu chưa đủ. Việc này không ngăn bạn cài quy trình. Xem các bước bên dưới.', updatedAt: '2026-11-24 23:50:00'),
    $entry(null, 'text', 'text.workflow.package.dry_run_steps', 'See the {count} steps', 'Xem {count} bước', updatedAt: '2026-11-24 23:50:00'),
    $entry(null, 'text', 'text.workflow.package.dry_run_row_ran', 'Tried for real with the sample data: no error.', 'Đã thử thật với dữ liệu mẫu: không lỗi.', updatedAt: '2026-11-24 23:50:00'),
    $entry(null, 'text', 'text.workflow.package.dry_run_row_failed', 'Tried with the sample data: this step reported an error.', 'Đã thử với dữ liệu mẫu: bước này báo lỗi.', updatedAt: '2026-11-24 23:50:00'),
    $entry(null, 'text', 'text.workflow.package.dry_run_row_approval', 'Would stop and wait for a person to approve. The test run went on as if it was approved.', 'Sẽ dừng lại chờ người duyệt. Lần chạy thử đi tiếp như thể đã được duyệt.', updatedAt: '2026-11-24 23:50:00'),
    $entry(null, 'text', 'text.workflow.package.dry_run_row_would', 'Not carried out in the test. When it really runs, it would: {what}.', 'Không thực hiện trong lần chạy thử. Khi chạy thật, bước này sẽ: {what}.', updatedAt: '2026-11-24 23:50:00'),
