    $entry(null, 'text', 'text.workflow.setup.q.reviewers_help', 'Everyone with the chosen permission may decide; people you name are told first.', 'Ai có quyền đã chọn đều được quyết định; những người được chọn đích danh sẽ được báo trước.', createdAt: '2026-11-24 23:00:00'),
    $entry(null, 'text', 'text.workflow.setup.q.notify_channel', 'Who is told at “:step”?', 'Báo cho ai ở bước “:step”?', createdAt: '2026-11-24 23:00:00'),
