    $entry(null, 'text', 'text.workflow.setup.q.credential', 'Which connected account does “:step” use?', 'Bước “:step” dùng tài khoản đã kết nối nào?', createdAt: '2026-11-24 23:00:00'),
    $entry(null, 'text', 'text.workflow.setup.q.credential_help', 'Pick an account saved in the workflow connections; its secret is never shown here.', 'Chọn một tài khoản đã lưu trong mục kết nối của quy trình; mật khẩu không bao giờ hiện ở đây.', createdAt: '2026-11-24 23:00:00'),
    $entry(null, 'text', 'text.workflow.setup.q.required_field', '“:step” needs: :field', 'Bước “:step” cần điền: :field', createdAt: '2026-11-24 23:00:00'),
