    $entry(null, 'text', 'text.workflow.preset.news.title', 'Parish news', 'Tin tức giáo xứ', createdAt: '2026-11-24 23:00:00'),
    $entry(null, 'text', 'text.workflow.preset.news.desc', 'News of parish events and announcements.', 'Tin sinh hoạt và thông báo của giáo xứ.', createdAt: '2026-11-24 23:00:00'),
    $entry(null, 'text', 'text.workflow.preset.news.source_facts', 'Facts from the source only', 'Chỉ nêu điều có trong nguồn', createdAt: '2026-11-24 23:00:00'),
    $entry(null, 'text', 'text.workflow.preset.news.source_facts_text', 'Every name, date, time, place and number in the article appears in the source material; the article adds no other details.', 'Mọi tên người, ngày giờ, địa điểm và con số trong bài đều có trong tài liệu nguồn; bài không thêm chi tiết nào khác.', createdAt: '2026-11-24 23:00:00'),
    $entry(null, 'text', 'text.workflow.preset.news.key_details', 'Main details included', 'Đủ thông tin chính', createdAt: '2026-11-24 23:00:00'),
    $entry(null, 'text', 'text.workflow.preset.news.key_details_text', 'The article states what happens, who organises it, the date and time, and the place, whenever the source gives them.', 'Bài nói rõ việc gì, ai tổ chức, ngày giờ và địa điểm, khi nguồn có các thông tin đó.', createdAt: '2026-11-24 23:00:00'),
    $entry(null, 'text', 'text.workflow.preset.news.names_titles', 'Correct names and titles', 'Đúng tên và chức danh', createdAt: '2026-11-24 23:00:00'),
    $entry(null, 'text', 'text.workflow.preset.news.names_titles_text', 'Parish names, saint names, full names and titles (Bishop, Father, Brother, Sister...) are written exactly as in the source.', 'Tên giáo xứ, tên thánh, họ tên và chức danh (Đức Giám mục, Linh mục, Thầy, Sơ...) được viết đúng như trong nguồn.', createdAt: '2026-11-24 23:00:00'),
    $entry(null, 'text', 'text.workflow.preset.news.respectful_tone', 'Formal tone', 'Giọng văn trang trọng', createdAt: '2026-11-24 23:00:00'),
    $entry(null, 'text', 'text.workflow.preset.news.respectful_tone_text', 'The tone is formal and respectful: no clickbait, no advertising, no political comment.', 'Giọng văn trang trọng, tôn trọng: không giật tít, không quảng cáo, không bình luận chính trị.', createdAt: '2026-11-24 23:00:00'),
    $entry(null, 'text', 'text.workflow.preset.news.no_private_info', 'No private information', 'Không nêu thông tin riêng', createdAt: '2026-11-24 23:00:00'),
    $entry(null, 'text', 'text.workflow.preset.news.no_private_info_text', 'The article gives no phone number, home address, health detail or other private information about parishioners unless the source published it openly.', 'Bài không nêu số điện thoại, địa chỉ nhà, tình trạng sức khoẻ hay thông tin riêng nào của giáo dân, trừ khi nguồn đã công bố công khai.', createdAt: '2026-11-24 23:00:00'),
    $entry(null, 'text', 'text.workflow.preset.reflection.title', 'Reflection on the Word of God', 'Bài suy niệm Lời Chúa', createdAt: '2026-11-24 23:00:00'),
    $entry(null, 'text', 'text.workflow.preset.reflection.desc', 'A reflection on the readings of a day.', 'Bài suy niệm theo các bài đọc trong ngày.', createdAt: '2026-11-24 23:00:00'),
    $entry(null, 'text', 'text.workflow.preset.reflection.scripture_reference', 'Correct Bible quotations', 'Trích dẫn Kinh Thánh đúng', createdAt: '2026-11-24 23:00:00'),
    $entry(null, 'text', 'text.workflow.preset.reflection.scripture_reference_text', 'Every Bible quotation names its book, chapter and verse and matches the readings of the stated day.', 'Mỗi câu Kinh Thánh được trích đều ghi rõ sách, chương, câu và khớp với bài đọc của ngày đã nêu.', createdAt: '2026-11-24 23:00:00'),
    $entry(null, 'text', 'text.workflow.preset.reflection.faithful_teaching', 'Faithful to Church teaching', 'Đúng giáo huấn của Hội Thánh', createdAt: '2026-11-24 23:00:00'),
    $entry(null, 'text', 'text.workflow.preset.reflection.faithful_teaching_text', 'Nothing in the text contradicts the teaching of the Catholic Church; uncertain points are not stated as fact.', 'Bài không có điều gì trái với giáo huấn của Hội Thánh Công giáo; điều chưa chắc chắn thì không khẳng định.', createdAt: '2026-11-24 23:00:00'),
    $entry(null, 'text', 'text.workflow.preset.reflection.tied_to_reading', 'Stays with the reading', 'Bám sát bài đọc', createdAt: '2026-11-24 23:00:00'),
    $entry(null, 'text', 'text.workflow.preset.reflection.tied_to_reading_text', 'The main idea comes from the stated Scripture reading and does not drift to another topic.', 'Ý chính của bài xuất phát từ bài đọc Lời Chúa đã nêu, không lạc sang chủ đề khác.', createdAt: '2026-11-24 23:00:00'),
    $entry(null, 'text', 'text.workflow.preset.reflection.practical_application', 'A way to live it', 'Có gợi ý sống Lời Chúa', createdAt: '2026-11-24 23:00:00'),
    $entry(null, 'text', 'text.workflow.preset.reflection.practical_application_text', 'The text gives at least one concrete suggestion for living the Word in daily life.', 'Bài có ít nhất một gợi ý cụ thể để người đọc sống Lời Chúa trong đời thường.', createdAt: '2026-11-24 23:00:00'),
    $entry(null, 'text', 'text.workflow.preset.reflection.no_invented_quotes', 'No invented quotations', 'Không bịa trích dẫn', createdAt: '2026-11-24 23:00:00'),
    $entry(null, 'text', 'text.workflow.preset.reflection.no_invented_quotes_text', 'The text attributes no words to the Pope, a saint or any author unless the source contains that quotation.', 'Bài không gán lời nói cho Đức Giáo hoàng, các thánh hay bất kỳ tác giả nào nếu nguồn không có câu đó.', createdAt: '2026-11-24 23:00:00'),
    $entry(null, 'text', 'text.workflow.preset.support_answer.title', 'Support answer', 'Trả lời câu hỏi hỗ trợ', createdAt: '2026-11-24 23:00:00'),
    $entry(null, 'text', 'text.workflow.preset.support_answer.desc', 'An answer to a question sent to the help desk.', 'Câu trả lời cho câu hỏi gửi đến bộ phận hỗ trợ.', createdAt: '2026-11-24 23:00:00'),
    $entry(null, 'text', 'text.workflow.preset.support_answer.answers_question', 'Answers the question', 'Trả lời đúng câu hỏi', createdAt: '2026-11-24 23:00:00'),
    $entry(null, 'text', 'text.workflow.preset.support_answer.answers_question_text', 'The answer addresses what the person actually asked, not a different question.', 'Câu trả lời giải quyết đúng điều người hỏi cần, không trả lời sang chuyện khác.', createdAt: '2026-11-24 23:00:00'),
    $entry(null, 'text', 'text.workflow.preset.support_answer.from_support_material', 'Based on the support material', 'Dựa trên tài liệu hỗ trợ', createdAt: '2026-11-24 23:00:00'),
    $entry(null, 'text', 'text.workflow.preset.support_answer.from_support_material_text', 'Every instruction, price, deadline and policy in the answer appears in the support material provided.', 'Mọi hướng dẫn, giá, thời hạn và chính sách trong câu trả lời đều có trong tài liệu hỗ trợ được cung cấp.', createdAt: '2026-11-24 23:00:00'),
    $entry(null, 'text', 'text.workflow.preset.support_answer.clear_steps', 'Clear steps', 'Các bước rõ ràng', createdAt: '2026-11-24 23:00:00'),
    $entry(null, 'text', 'text.workflow.preset.support_answer.clear_steps_text', 'When several steps are needed, the answer lists them in order, one action per step.', 'Khi cần làm nhiều bước, câu trả lời liệt kê từng bước theo thứ tự, mỗi bước một việc.', createdAt: '2026-11-24 23:00:00'),
    $entry(null, 'text', 'text.workflow.preset.support_answer.plain_polite', 'Polite and plain', 'Lịch sự, dễ hiểu', createdAt: '2026-11-24 23:00:00'),
    $entry(null, 'text', 'text.workflow.preset.support_answer.plain_polite_text', 'The wording is polite and plain, with no technical terms unless they are needed.', 'Lời lẽ lịch sự, dễ hiểu, không dùng thuật ngữ kỹ thuật khi không cần.', createdAt: '2026-11-24 23:00:00'),
    $entry(null, 'text', 'text.workflow.preset.support_answer.no_promises', 'No unsupported promises', 'Không hứa điều chưa chắc', createdAt: '2026-11-24 23:00:00'),
    $entry(null, 'text', 'text.workflow.preset.support_answer.no_promises_text', 'The answer promises no refund, compensation or handling time that the support material does not state.', 'Câu trả lời không hứa hoàn tiền, đền bù hay thời gian xử lý mà tài liệu hỗ trợ không nêu.', createdAt: '2026-11-24 23:00:00'),
    $entry(null, 'text', 'text.workflow.preset.support_answer.no_secrets', 'Never asks for secrets', 'Không hỏi thông tin bí mật', createdAt: '2026-11-24 23:00:00'),
    $entry(null, 'text', 'text.workflow.preset.support_answer.no_secrets_text', 'The answer never asks the person to send a password, a one-time code or a card number.', 'Câu trả lời không bao giờ yêu cầu người hỏi gửi mật khẩu, mã xác thực một lần hay số thẻ.', createdAt: '2026-11-24 23:00:00'),
