    $entry(null, 'text', 'text.workflow.preset.seo_description.desc', 'The short description shown in lists and search results.', 'Đoạn mô tả ngắn hiện trong danh sách và kết quả tìm kiếm.', createdAt: '2026-11-24 23:00:00'),
