    $entry(null, 'text', 'text.workflow.preset.seo_description.matches_content', 'Matches the article', 'Đúng nội dung bài', createdAt: '2026-11-24 23:00:00'),
    $entry(null, 'text', 'text.workflow.preset.seo_description.matches_content_text', 'The description says only what the article contains and promises nothing the article lacks.', 'Mô tả chỉ nói điều có trong bài, không hứa hẹn điều bài không có.', createdAt: '2026-11-24 23:00:00'),
