    $entry(null, 'text', 'text.workflow.preset.seo_description.keyword_text', 'The description contains the main keyword of the article once, used naturally.', 'Mô tả có từ khoá chính của bài một lần, viết tự nhiên.', createdAt: '2026-11-24 23:00:00'),
