    $entry(null, 'text', 'text.workflow.preset.seo_description.full_diacritics', 'Full Vietnamese diacritics', 'Tiếng Việt có dấu đầy đủ', createdAt: '2026-11-24 23:00:00'),
    $entry(null, 'text', 'text.workflow.preset.seo_description.full_diacritics_text', 'When the description is in Vietnamese, every word has full and correct diacritics.', 'Khi mô tả viết bằng tiếng Việt, mọi chữ đều có dấu đầy đủ và đúng chính tả.', createdAt: '2026-11-24 23:00:00'),
    $entry(null, 'text', 'text.workflow.preset.article_quality.title', 'Article quality', 'Chất lượng bài viết', createdAt: '2026-11-24 23:00:00'),
    $entry(null, 'text', 'text.workflow.preset.article_quality.desc', 'Scores an article on accuracy, clarity, usefulness and style.', 'Chấm điểm bài viết theo độ chính xác, độ rõ ràng, tính hữu ích và văn phong.', createdAt: '2026-11-24 23:00:00'),
