    $entry(null, 'text', 'text.workflow.preset.church_profile.desc', 'The checks the church-story JEV makes: every dated or numeric claim must be backed by a cited source excerpt.', 'Những điều JEV kiểm tra ở bài về nhà thờ: mọi mốc thời gian và con số phải có đoạn trích nguồn xác nhận.', createdAt: '2026-11-24 23:00:00'),
