    $entry(null, 'text', 'text.workflow.preset.church_profile.dates_supported_text', 'Every year or date in the story (founding, building, consecration, renovation) is supported by one of the cited source excerpts.', 'Mọi năm hoặc ngày tháng trong bài (thành lập, xây dựng, cung hiến, trùng tu) đều được một đoạn trích nguồn đã dẫn xác nhận.', createdAt: '2026-11-24 23:00:00'),
    $entry(null, 'text', 'text.workflow.preset.church_profile.numbers_supported', 'Numbers backed by a source', 'Con số có nguồn', createdAt: '2026-11-24 23:00:00'),
    $entry(null, 'text', 'text.workflow.preset.church_profile.numbers_supported_text', 'Every number in the story (parishioners, size, count of priests or chapels) is supported by one of the cited source excerpts.', 'Mọi con số trong bài (số giáo dân, kích thước, số linh mục hay nhà nguyện) đều được một đoạn trích nguồn đã dẫn xác nhận.', createdAt: '2026-11-24 23:00:00'),
    $entry(null, 'text', 'text.workflow.preset.church_profile.no_contradiction', 'Does not contradict the sources', 'Không mâu thuẫn với nguồn', createdAt: '2026-11-24 23:00:00'),
    $entry(null, 'text', 'text.workflow.preset.church_profile.no_contradiction_text', 'Nothing in the story contradicts any of the cited source excerpts.', 'Không điều gì trong bài mâu thuẫn với các đoạn trích nguồn đã dẫn.', createdAt: '2026-11-24 23:00:00'),
    $entry(null, 'text', 'text.workflow.preset.church_profile.no_unsourced_claims', 'Nothing beyond the cited sources', 'Không thêm thông tin ngoài nguồn đã dẫn', createdAt: '2026-11-24 23:00:00'),
    $entry(null, 'text', 'text.workflow.preset.church_profile.no_unsourced_claims_text', 'A dated or numeric claim that no excerpt covers counts as not supported.', 'Một mốc thời gian hay con số không có đoạn trích nào xác nhận thì bị coi là không có nguồn.', createdAt: '2026-11-24 23:00:00'),
