    $entry(null, 'text', 'text.workflow.library.update_in_place_note', 'The workflow is updated in place and keeps your setup answers. The version that runs now stays until you publish the new one.', 'Quy trình được cập nhật tại chỗ và giữ nguyên các câu trả lời Thiết lập. Bản đang chạy giữ nguyên cho tới khi bạn xuất bản bản mới.', createdAt: '2026-11-25 17:00:00'),
    $entry(null, 'text', 'text.workflow.library.update_footnote', 'After updating, the “Setup” screen opens so you can answer any new question.', 'Cập nhật xong sẽ mở màn hình “Thiết lập” để bạn trả lời câu hỏi mới, nếu có.', createdAt: '2026-11-25 17:00:00'),
