    $entry(null, 'text', 'text.workflow.library.error_hint.not_available', 'Ask the website manager to turn on the missing module, then install again.', 'Nhờ người quản trị website bật module còn thiếu, rồi cài lại.', createdAt: '2026-11-25 14:00:00'),
    $entry(null, 'text', 'text.workflow.library.error_hint.not_installable', 'Nothing was changed on this website. Tell iSPA so the template can be fixed.', 'Website chưa bị thay đổi gì. Hãy báo cho iSPA để mẫu được sửa.', createdAt: '2026-11-25 14:00:00'),
