    // ── Workflow auto-publish calibration — UI (2026-11-24) ───────────────────────────────────────────────────────────
    $entry(null, 'text', 'text.workflow.auto_publish.title', 'Auto-publish when JEV is sure', 'Tự đăng khi JEV chắc chắn', createdAt: '2026-11-25 20:00:00'),
