    $entry(null, 'text', 'text.workflow.auto_publish.learning_intro', 'Every item waits for a person. Each time you approve or reject, the system records whether JEV thought the same as you.', 'Mọi bài đang chờ người duyệt. Mỗi lần bạn duyệt hoặc từ chối, hệ thống ghi lại JEV có cùng ý với bạn không.', createdAt: '2026-11-25 20:00:00'),
    $entry(null, 'text', 'text.workflow.auto_publish.decisions', 'Decisions by reviewers', 'Quyết định của người duyệt', createdAt: '2026-11-25 20:00:00'),
