    $entry(null, 'text', 'text.workflow.auto_publish.need_agreement', 'There are enough decisions, but JEV does not agree with the reviewers in {percent}% of them yet.', 'Đã đủ số quyết định, nhưng JEV chưa trùng ý với người duyệt tới {percent}%.', createdAt: '2026-11-25 20:00:00'),
    $entry(null, 'text', 'text.workflow.auto_publish.ready_intro', '{decided} decisions, JEV agrees in {percent}% of them. Once turned on, an item that meets all three conditions below is published right away, without waiting for a person.', '{decided} quyết định, JEV trùng ý {percent}%. Bật lên thì bài nào đủ cả ba điều kiện dưới đây sẽ được đăng ngay, không chờ người.', createdAt: '2026-11-25 20:00:00'),
    $entry(null, 'text', 'text.workflow.auto_publish.condition_pass', 'JEV concludes “Pass”', 'JEV kết luận “Đạt”', createdAt: '2026-11-25 20:00:00'),
    $entry(null, 'text', 'text.workflow.auto_publish.condition_level', 'JEV is at least as sure as the chosen level', 'Độ chắc của JEV từ mức đã chọn trở lên', createdAt: '2026-11-25 20:00:00'),
    $entry(null, 'text', 'text.workflow.auto_publish.condition_no_flag', 'The item has no quality flag (a missing source, dates that do not match…)', 'Bài không có cờ chất lượng nào (thiếu nguồn, ngày tháng không khớp…)', createdAt: '2026-11-25 20:00:00'),
    $entry(null, 'text', 'text.workflow.auto_publish.level', 'How sure JEV must be to publish on its own', 'Mức chắc chắn để tự đăng', createdAt: '2026-11-25 20:00:00'),
    $entry(null, 'text', 'text.workflow.auto_publish.estimate', 'Of the last {of} reviewed items, level {level} would publish about {auto} on its own; the other {rest} would still wait for a person.', 'Với {of} bài đã duyệt gần nhất, mức {level} sẽ tự đăng khoảng {auto} bài; {rest} bài còn lại vẫn chờ người.', createdAt: '2026-11-25 20:00:00'),
    $entry(null, 'text', 'text.workflow.auto_publish.change_control', 'Turning on auto-publish is an important change: you confirm your identity again, and a second person reviews it when you publish the workflow.', 'Bật tự đăng là thay đổi quan trọng: bạn cần xác nhận lại danh tính, và người thứ hai duyệt khi xuất bản.', createdAt: '2026-11-25 20:00:00'),
    $entry(null, 'text', 'text.workflow.auto_publish.level_change_note', 'Changing the level is also an important change and goes through the same check when you publish.', 'Đổi mức cũng là thay đổi quan trọng và qua cùng bước kiểm tra khi bạn xuất bản.', createdAt: '2026-11-25 20:00:00'),
    $entry(null, 'text', 'text.workflow.auto_publish.pending_publish', 'This choice is only in the draft. It takes effect after you save and publish the workflow.', 'Lựa chọn này mới nằm trong bản nháp. Nó có hiệu lực sau khi bạn lưu và xuất bản quy trình.', createdAt: '2026-11-25 20:00:00'),
    $entry(null, 'text', 'text.workflow.auto_publish.tile_auto', 'published by JEV', 'tự đăng', createdAt: '2026-11-25 20:00:00'),
    $entry(null, 'text', 'text.workflow.auto_publish.tile_human', 'waited for a person', 'chờ người', createdAt: '2026-11-25 20:00:00'),
    $entry(null, 'text', 'text.workflow.auto_publish.tile_withdrawn', 'taken back', 'bị rút lại', createdAt: '2026-11-25 20:00:00'),
    $entry(null, 'text', 'text.workflow.auto_publish.last_30_days', 'Last 30 days', '30 ngày gần nhất', createdAt: '2026-11-25 20:00:00'),
    $entry(null, 'text', 'text.workflow.auto_publish.withdraw_note', 'An item JEV published stays in the approvals inbox with the mark “Approved by JEV”. You can take it back at any time; each time counts as JEV being wrong.', 'Bài tự đăng vẫn nằm trong hộp duyệt với dấu “JEV tự duyệt”. Bạn rút lại được bất cứ lúc nào; mỗi lần rút lại tính là JEV chưa đúng.', createdAt: '2026-11-25 20:00:00'),
    $entry(null, 'text', 'text.workflow.auto_publish.pause_rule', 'Auto-publish pauses itself when JEV agrees in less than {percent}% of the last {count} decisions; every item then waits for a person again and the managers are told.', 'Tự tạm dừng nếu trong {count} quyết định gần nhất JEV trùng ý dưới {percent}%; mọi bài quay về chờ người duyệt và người quản lý được báo.', createdAt: '2026-11-25 20:00:00'),
    $entry(null, 'text', 'text.workflow.auto_publish.paused_body', 'Auto-publish is paused: in the latest decisions JEV agreed with the reviewers less than {percent}% of the time. Every item waits for a person now. It resumes on its own when the agreement recovers, or you can turn it off.', 'Tự đăng đang tạm dừng: trong các quyết định gần nhất JEV trùng ý với người duyệt dưới {percent}%. Lúc này mọi bài đều chờ người duyệt. Tự đăng sẽ chạy lại khi mức trùng ý hồi phục, hoặc bạn có thể tắt hẳn.', createdAt: '2026-11-25 20:00:00'),
    $entry(null, 'text', 'text.workflow.auto_publish.card_learning', 'A person reviews everything · {decided}/{required}', 'Người duyệt tất cả · {decided}/{required}', createdAt: '2026-11-25 20:00:00'),
    $entry(null, 'text', 'text.workflow.auto_publish.card_learning_plain', 'A person reviews everything', 'Người duyệt tất cả', createdAt: '2026-11-25 20:00:00'),
    $entry(null, 'text', 'text.workflow.auto_publish.card_on', 'JEV approves when sure ≥ {level} · the rest wait for a person', 'JEV tự duyệt khi chắc ≥ {level} · còn lại chờ người', createdAt: '2026-11-25 20:00:00'),
    $entry(null, 'text', 'text.workflow.auto_publish.card_paused', 'Auto-publish paused', 'Tự đăng tạm dừng', createdAt: '2026-11-25 20:00:00'),
    $entry(null, 'text', 'text.workflow.issue.auto_approval_not_ready', 'Auto-publish cannot be turned on yet: there are not enough reviewer decisions, or JEV does not agree with them often enough. Turn it off on the review step, then save again.', 'Chưa bật được tự đăng: chưa đủ quyết định của người duyệt, hoặc JEV chưa trùng ý đủ nhiều. Hãy tắt tự đăng ở bước duyệt rồi lưu lại.', createdAt: '2026-11-25 20:00:00'),
    $entry(null, 'text', 'text.workflow.guard.problem.auto_approval_not_ready', 'Auto-publish cannot be turned on yet: there are not enough reviewer decisions, or JEV does not agree with them often enough.', 'Chưa bật được tự đăng: chưa đủ quyết định của người duyệt, hoặc JEV chưa trùng ý đủ nhiều.', createdAt: '2026-11-25 20:00:00'),
